files.content:
.popover{
  margin:0;
  inset:auto;
  position-area:bottom span-right;
  position-try-fallbacks:flip-block, flip-inline;
  margin-block:var(--s-1);
  width:max-content;
  min-width:var(--w-popover-min);
  max-width:min(var(--w-popover), calc(100vw - var(--s-8)));
  padding:var(--s-4);
  background:var(--obsidian-900);
  color:var(--obsidian-100);
  border:var(--bw-1) solid var(--obsidian-700);
  border-radius:var(--r-lg);
  box-shadow:var(--sh-3);
  font-family:var(--font-sans);
  font-size:var(--t-small);
  line-height:var(--lh-snug);
  opacity:0;
  transform:translateY(calc(-1 * var(--s-1)));
  transition:opacity var(--d-quick) var(--ease-accel), transform var(--d-quick) var(--ease-accel), overlay var(--d-quick) var(--ease-accel) allow-discrete, display var(--d-quick) var(--ease-accel) allow-discrete;
}
.popover:popover-open{
  opacity:1;
  transform:none;
  transition-timing-function:var(--ease-decel);
}
.popover-top{
  position-area:top span-right;
  transform:translateY(var(--s-1));
}
.popover-end{
  position-area:right span-bottom;
  margin-block:0;
  margin-inline:var(--s-1);
  transform:translateX(calc(-1 * var(--s-1)));
}
@media (max-width:480px){
  .popover-end{
    position-area:bottom span-right;
    margin-block:var(--s-1);
    margin-inline:0;
    transform:translateY(calc(-1 * var(--s-1)));
  }
}
.popover-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--s-4);
  margin-bottom:var(--s-3);
}
.popover-title{
  margin:0;
  font-size:var(--t-body);
  font-weight:700;
  line-height:var(--lh-snug);
}
.popover-body{
  display:grid;
  gap:var(--s-3);
  color:var(--obsidian-200);
}
.popover-foot{
  display:flex;
  justify-content:flex-end;
  gap:var(--s-2);
  margin-top:var(--s-4);
}
@media (prefers-reduced-motion: reduce){
  .popover, .popover-top, .popover-end{
    transition:none;
    transform:none;
  }
}
.popover{
  width:min(100%, calc(var(--s-32) * 2.5));
}
.popover){
  display:block;
  position:static;
  inset:auto;
  margin:0;
  opacity:1;
  transform:none;
}
